from geoloc_connector.core.logger import app_logger

from geoloc_connector.services.file_service import FileService

from tasks.faststream_app import MSISDN_QUEUE, broker


def get_file_service() -> FileService:
    return FileService()


@broker.subscriber(
    MSISDN_QUEUE,
)
async def process_msisdn_file(payload: dict[str, str]) -> str:
    file_url = payload["file_url"]
    list_id = payload["list_id"]
    tenant_id = payload["tenant_id"]

    app_logger.info("msisdn_file_task_start", file_url=file_url, list_id=list_id, tenant_id=tenant_id)

    try:
        service = get_file_service()

        total_lines = await service.process_msisdn_file_from_minio(
            file_url=file_url, list_id=list_id, tenant_id=tenant_id
        )

        app_logger.info(
            "msisdn_file_task_success",
            file_url=file_url, list_id=list_id, tenant_id=tenant_id, total_lines=total_lines
        )
        return f"File processed with list_id: {list_id}, lines: {total_lines}"
    except Exception:
        app_logger.error(
            "msisdn_file_task_failed",
            exc_info=True, file_url=file_url, list_id=list_id, tenant_id=tenant_id
        )
        raise

from tasks.faststream_app import REGULAR_CAMPAIGN_QUEUE, REGULAR_CAMPAIGN_RETRY_QUEUE, broker

from tasks.regular_campaign.retry import retry_failed_dispatches

from tasks.regular_campaign.workflow import RegularCampaignExecutionWorkflow


@broker.subscriber(
    REGULAR_CAMPAIGN_QUEUE,
)
async def run_regular_campaign_execution(payload: dict[str, str]) -> str:
    campaign_id = payload["campaign_id"]
    execution_id = payload["execution_id"]
    tenant_id = payload["tenant_id"]

    workflow = RegularCampaignExecutionWorkflow()

    return await workflow.execute(campaign_id=campaign_id, execution_id=execution_id, tenant_id=tenant_id)


@broker.subscriber(
    REGULAR_CAMPAIGN_RETRY_QUEUE,
)
async def retry_failed_regular_campaign_dispatches() -> str:
    return await retry_failed_dispatches()

