from faststream import FastStream

from geoloc_connector.core.database import init_db

from geoloc_connector.core.logger import app_logger


def register_worker_bootstrap(app: FastStream) -> None:
    @app.on_startup
    async def init_worker_database() -> None:
        try:
            await init_db()
            app_logger.info("worker_database_init_success")
        except Exception:
            app_logger.error("worker_database_init_failed", exc_info=True)
            raise

from typing import Iterable, Iterator, TypeVar

T = TypeVar("T")

def chunked(iterable: Iterable[T], size: int) -> Iterator[list[T]]:
    if size <= 0:
        raise ValueError("size must be a positive integer")

    batch: list[T] = []
    for item in iterable:
        batch.append(item)
        if len(batch) >= size:
            yield batch
            batch = []
    if batch:
        yield batch
